-- kontakt, afmeldingsmail, indløsning og nyt logo. 10 adgange á 1.800 kr. ekskl. moms:
-- 9 som timepræmier og 1 i præmiepuljen (uændret).
UPDATE partner
   SET firmanavn = 'Sandhed Group Ltd',
       cvr = '',
       adresse = 'Unit S140, SOHO The Strand, Fawwara Building, Triq L-Imsida, Gzira GZR 1401, Malta (reg.nr. C116249, VAT MT33018730)',
       hjemmeside = 'https://www.sandhed.com/da',
       privatlivspolitik = 'https://www.sandhed.com/privacy',
       kort_beskrivelse = 'Sandhed er et facility management system, som giver webshops, lagerhoteller og produktionsvirksomheder et live 3D-overblik over lagerdata, udstyr og drift, så de kan finde problemer hurtigere og optimere deres arbejdsgange.',
       produktkategori = 'nyheder og tilbud om Sandheds løsninger til digitale tvillinger, lageroverblik, sporing af udstyr, vedligehold og AI i driften',
       kontakt_navn = 'Lasse Ran Carlsen',
       kontakt_email = 'hello@sandhed.com',
       kontakt_telefon = '+45 40 44 35 89',
       levering_navn = 'Lasse Ran Carlsen',
       levering_email = 'hello@sandhed.com',
       afmeld_email = 'legal@sandhed.com',
       praemie_indloesning = 'Vinderen skriver til hello@sandhed.com med navn, firmanavn og den ønskede mailadresse til adgangen samt en henvisning til Packrush. Sandhed opretter og aktiverer derefter de 6 måneders gratis adgang.',
       praemie_ikke_med = 'Præmien omfatter softwareadgangen. Hardware som sensorer og tags er ikke med.',
       praemie_sidste_frist = DATE '2027-03-31',
       logo = decode('', 'base64'),
       logo_type = 'image/png',
       opdateret = now()
 WHERE slug = 'sandhed';
